                if (rdramPtr) tickMod._free(rdramPtr);
                if (cpuPtr) tickMod._free(cpuPtr);
                if (hiddenPtr) tickMod._free(hiddenPtr);
                if (hlePtr) tickMod._free(hlePtr);
