                        const localAtT = _localInputs[applyFrame] || KNShared.ZERO_INPUT;
                        const preCu = tickMod._kn_pre_tick(
                          localAtT.buttons | 0,
                          localAtT.lx | 0,
                          localAtT.ly | 0,
                          localAtT.cx | 0,
                          localAtT.cy | 0,
                          -1,
                        );
