    _rbShadowHoldUntil = performance.now() + RB_SHADOW_OVERLAY_HOLD_MS;
    _rbVisualFreezeActive = true;
    _rbShadowVisibleStepBase = stats.stepAcks;
    _rbShadowVisibleCommits = 0;
