        const rdram = _shadowTransferBuffer(split.rdram);
        const cpu = _shadowTransferBuffer(split.cpu);
        const hidden = _shadowTransferBuffer(split.hidden);
        const hle = _shadowTransferBuffer(split.hle);
        const transfer = [rdram, cpu];
