    for (let slot = 0; slot < 4; slot++) writeInputToMemory(slot, 0);
    _checkpoint.slots.forEach((slot, i) => writeInputToMemory(slot, _inputFromTuple(step.inputs[i])));
    m._kn_reset_audio?.();
